var t=`1206-pupusas-de-queso`;var i=`world-1206`;var o=`SV`;var n=`central-america-caribbean`;var s=8;var r=56;var l={en:`Pupusas de Queso`,ua:`Пупуси з сиром`};var u={en:`Pupusas de Queso is a dish from El Salvador featuring masa harina, queso fresco, mozzarella, white cabbage. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Пупуси з сиром, страва кухні країни Сальвадор з такими основними складниками: маса харіна, кесо фреско, моцарела, білоголова капуста. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var d=[{en:`Mix the corn flour with the measured water and salt until a soft cohesive, non-sticky masa forms. Rest covered for about 10 minutes; this gluten-free dough does not become elastic like wheat dough.`,ua:`Змішайте кукурудзяне борошно із зазначеною водою й сіллю до м’якої цілісної маси, що не липне. Накрийте на приблизно 10 хвилин; таке безглютенове тісто не стає еластичним, як пшеничне.`,t:[`mixing`,`kneading`,`resting-dough`],m:12,i:[[`masa-harina`,540,`g`],[`water`,650,`ml`],[`table-salt`,9,`g`]]},{en:`Prepare the filling ingredients: cook or soften any components that require it, let cool, then mix into an even filling.`,ua:`Підготуйте складники начинки: ті, що потребують теплової обробки, приготуйте, охолодіть і змішайте в однорідну начинку.`,t:[`chopping`,`mixing`],m:5,i:[[`queso-fresco`,290,`g`],[`mozzarella`,180,`g`]]},{en:`Shape, press or roll the prepared dough or mixture into portions appropriate to this dish.`,ua:`Розпластайте, розкачайте або сформуйте з підготовленого тіста чи маси порції потрібної форми.`,t:[`pressing`,`rolling-out-dough`],m:14,i:[]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 20 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 20 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:20,i:[[`canola-oil`,55,`ml`]]},{en:`Arrange the fully cooked and prepared parts of the dish on plates or in the intended serving vessel, adding the listed toppings or accompaniments just before serving.`,ua:`Зберіть повністю приготовані частини страви на тарілках або в посуді для подавання, додавши зазначені топінги та доповнення безпосередньо перед подаванням.`,t:[`layered-assembly`,`garnishing`],m:5,i:[[`white-cabbage`,250,`g`],[`white-vinegar`,65,`ml`]]}];var h={slug:t,id:i,country:`SV`,region:n,servings:8,minutes:56,title:l,text:u,steps:d};export{o as country,h as default,i as id,r as minutes,n as region,s as servings,t as slug,d as steps,u as text,l as title};